local serializer=...

local encodingservice=game:GetService("EncodingService")
local mapsdata=[[]]

mapsdata=buffer.tostring(encodingservice:Base64Decode(buffer.fromstring(mapsdata)))
return serializer.DeserializeInstance(mapsdata,{
	IsDataCompressed=true,
	IsBase94Encoded=false,
	AnnoyingConsolePrints=true,
	IsCompressedWithLegacyCompressor=false,
	ProperlyDeserializeMeshParts=true,
	ParentInstanceWhileDeserializing=nil,
})